local function clean(text: string): string
local out = text
if filterFn then
local ok, filtered = pcall(filterFn, out)
if ok and type(filtered) == "string" then
out = filtered
end
end
if maxLen and #out > maxLen then
out = string.sub(out, 1, maxLen)
end
return out
end
