local OPTS = ...
OPTS = type(OPTS) == "table" and OPTS or {}

local API = tostring(OPTS.Api or "")
local SCREEN = type(OPTS.Screen) == "function" and OPTS.Screen or nil
local DISCORD = tostring(OPTS.Discord or "")
local WHERE = tostring(OPTS.Where or "")
local NOTE = tostring(OPTS.Note or "")
local REASON = tostring(OPTS.Reason or "")
local CODE = tostring(OPTS.Code or "NO KEY")
local STALE = OPTS.Stale == true
local TEST = OPTS.Test == true
local QUERY = TEST and "?keytest=1" or ""
local FREE = "get the free key in discord, then paste it below."
local INVITE = DISCORD ~= "" and DISCORD or (WHERE ~= "" and WHERE or "https://discord.gg/joinuranium")
local ADDRESS = INVITE:gsub("^https?://", ""):gsub("/+$", "")

local KEYFOLDER = "uranium"
local KEYFILE = "uranium/key.json"

local HttpServ = game:GetService("HttpService")

local function try(fn, ...)
	local succ, res = pcall(fn, ...)
	if succ then return res end
	return nil
end

local function logWarning(msg)
	return warn(`[Uranium] {msg}`)
end

local httpRequest = (type(http) == "table" and type(http.request) == "function" and http.request)
	or (type(http_request) == "function" and http_request)
	or (type(request) == "function" and request)
	or (type(syn) == "table" and type(syn.request) == "function" and syn.request)

local function tidy(value)
	if type(value) ~= "string" then return "" end
	return (value:gsub("%s+", ""):upper())
end

local function readKey()
	if type(isfile) ~= "function" or type(readfile) ~= "function" then return "" end
	if not try(isfile, KEYFILE) then return "" end

	local raw = try(readfile, KEYFILE)
	if type(raw) ~= "string" or raw == "" then return "" end

	local data = try(function() return HttpServ:JSONDecode(raw) end)
	if type(data) == "table" and type(data.key) == "string" then return data.key end
	if raw:sub(1, 1) == "{" then return "" end
	return tidy(raw)
end

local function writeKey(key)
	if type(writefile) ~= "function" then return end
	if type(isfolder) == "function" and type(makefolder) == "function"
		and not try(isfolder, KEYFOLDER) then
		try(makefolder, KEYFOLDER)
	end
	try(function()
		writefile(KEYFILE, HttpServ:JSONEncode({ key = key, saved = os.time() }))
	end)
end

local function fetchLoader(key)
	local url = `{API}/v1/loader?k={HttpServ:UrlEncode(key)}{TEST and "&keytest=1" or ""}`
	local src = try(function() return game:HttpGet(url, true) end)
	if type(src) ~= "string" or src == "" then return nil end
	return src
end

local function runLoader(src)
	local fn, err = loadstring(src)
	if not fn then
		logWarning(`loader didn't compile: {err}`)
		return false
	end
	local ok, res = pcall(fn)
	if not ok then
		logWarning(`loader errored: {res}`)
		return false
	end
	return true
end

local function redeem(value)
	local key = tidy(value)
	if key == "" then return false, "enter your key first." end
	if not httpRequest then return false, "your executor can't send requests." end

	local hwid = try(gethwid)
	local res = try(httpRequest, {
		Url = `{API}/v1/key{QUERY}`,
		Method = "POST",
		Headers = { ["Content-Type"] = "application/json" },
		Body = HttpServ:JSONEncode({ key = key, hwid = hwid and tostring(hwid) or nil }),
	})
	if not res then return false, "couldn't reach the server. try again in a moment." end

	local data = try(function() return HttpServ:JSONDecode(res.Body or "") end)
	if type(data) ~= "table" then return false, "the server sent something back we couldn't read." end
	if not data.ok then return false, tostring(data.reason or "that key didn't work.") end

	local saved = type(data.key) == "string" and data.key ~= "" and data.key or key
	writeKey(saved)
	return true, saved
end

local override = (type(getgenv) == "function") and getgenv().URANIUM_KEY or nil
local key = TEST and "" or tidy(override)
if key == "" and not STALE and not TEST then key = readKey() end

if key ~= "" and not STALE then
	local src = fetchLoader(key)
	if src and runLoader(src) then return end
end

if not SCREEN then
	return logWarning(REASON ~= "" and REASON
		or `a key is required — put it in {KEYFILE} or set getgenv().URANIUM_KEY before running`)
end

local handle
local busy = false

local function report(ui, message, good)
	if ui and type(ui.Error) == "function" and not good then
		if pcall(ui.Error, ui, message) then return end
	end
	if ui and type(ui.Success) == "function" and good then
		if pcall(ui.Success, ui, message) then return end
	end
	if handle and type(handle.Flash) == "function" then
		pcall(handle.Flash, handle, message)
	end
end

local function setBusy(ui, on)
	if ui and type(ui.Busy) == "function" then pcall(ui.Busy, ui, on) end
end

local function attempt(value, ui)
	if busy then return end
	busy = true
	setBusy(ui, true)

	local ok, result = redeem(value)
	if not ok then
		busy = false
		setBusy(ui, false)
		report(ui, result, false)
		return
	end

	report(ui, "key accepted, loading.", true)

	local src = fetchLoader(result)
	if not src then
		busy = false
		setBusy(ui, false)
		report(ui, "key worked, but the loader didn't come down. try again.", false)
		return
	end

	pcall(function() handle:Close() end)
	task.defer(runLoader, src)
end

